package com.alpharip.staffmod.BuildTimelapse.core;
import com.alpharip.staffmod.BuildTimelapse.timeline.*;import java.io.*;import java.util.*;
/** Local-only project metadata and timeline marker persistence. PNG frames remain separate. */
public final class FileProjectStore implements ProjectStore {
 private final File root;public FileProjectStore(File r){if(r==null)throw new IllegalArgumentException("root");root=r;}
 public void save(BuildTimelapseProject p,Timeline t)throws IOException{if(p==null||t==null)throw new IllegalArgumentException("project/timeline");if(!root.exists()&&!root.mkdirs())throw new IOException("Cannot create project directory");Properties v=new Properties();v.setProperty("format","1");v.setProperty("id",p.getId());v.setProperty("name",p.getName());v.setProperty("world",p.getWorld());v.setProperty("created",Long.toString(p.getCreated()));v.setProperty("notes",p.getNotes());v.setProperty("marker.count",Integer.toString(t.getMarkers().size()));int n=0;for(TimelineMarker m:t.getMarkers()){String k="marker."+(n++)+".";v.setProperty(k+"time",Long.toString(m.getTimeMillis()));v.setProperty(k+"label",m.getLabel());v.setProperty(k+"kind",m.getKind().name());}File tmp=new File(root,p.getId()+".tmp"),dst=new File(root,p.getId()+".btproj");try(OutputStream o=new BufferedOutputStream(new FileOutputStream(tmp))){v.store(o,"Build Timelapse project");}if(dst.exists()&&!dst.delete())throw new IOException("Cannot replace project");if(!tmp.renameTo(dst))throw new IOException("Atomic rename failed");}
 private Properties read(String id)throws IOException{File f=new File(root,id+".btproj");if(!f.isFile())throw new FileNotFoundException(f.toString());Properties v=new Properties();try(InputStream in=new BufferedInputStream(new FileInputStream(f))){v.load(in);}if(!"1".equals(v.getProperty("format")))throw new IOException("Unsupported project format");return v;}
 public BuildTimelapseProject load(String id)throws IOException{Properties v=read(id);BuildTimelapseProject p=new BuildTimelapseProject(v.getProperty("id"),v.getProperty("name"),v.getProperty("world"),Long.parseLong(v.getProperty("created")));p.setNotes(v.getProperty("notes",""));return p;}
 public Timeline loadTimeline(String id)throws IOException{Properties v=read(id);Timeline t=new Timeline();int count=Integer.parseInt(v.getProperty("marker.count","0"));for(int n=0;n<count;n++){String k="marker."+n+".";t.addMarker(new TimelineMarker(Long.parseLong(v.getProperty(k+"time")),v.getProperty(k+"label"),TimelineMarkerKind.valueOf(v.getProperty(k+"kind"))));}return t;}
}
